import {Cloudwake,CLOUD_ROUTES,HARBORS} from './cloudwake-core.js';
import {Inkfin,REEFS} from './inkfin-core.js';
import {createCloudScene} from './cloudwake-scene.js';
import {drawInkfin} from './inkfin-art.js';
import {creativeCover} from './covers.js';
import {createCreativeInput} from './input.js';
import {create3DScene,createSynthAudio} from '../3d/index.js';
import {createInstructionGate} from '../game-instructions.js';
import {DB,player,commitRound,unlock,save} from '../data.js';
import {audio,muteBackground} from '../audio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openCreativeGames(host,{kind,exit,notify}){const cloud=kind==='cloudwake',title=cloud?'Cloudwake Couriers':'Inkfin Lagoon',levels=cloud?CLOUD_ROUTES:REEFS;let level=1,difficulty=2,ids=[DB.active],quality='medium',disposed=false,serial=0,model=null,runtime=null,scene=null,input=null,sound=null,musicSound=null,paused=false,raf=0,stamp=0,acc=0,recorded=false,melody=0;const q=s=>host.querySelector(s),clean=[];
 const gate=createInstructionGate({game:kind,onBack:()=>setup(),onReview(){setPaused(true);return()=>{};}});
 function cleanup(){serial++;cancelAnimationFrame(raf);input?.dispose();scene?.dispose();runtime?.dispose();sound?.dispose();musicSound?.dispose();input=scene=runtime=sound=musicSound=null;for(const f of clean.splice(0))f();muteBackground(false);}
 function setup(){cleanup();model=null;host.innerHTML=`<section class="creative-new ${kind}"><header><button id="cnExit" class="btn secondary">← ARCADE</button><span class="eyebrow">TWO NEW WORLDS · ORIGINAL PLAY</span></header><div class="cn-title-art">${creativeCover(kind)}</div><h1>${title}</h1><p>${cloud?'Catch a crosswind. Carry something precious. Fly your sail-wing courier between floating harbor towns, choosing when to climb, boost and brake.':'A little school. A living sea. Call your illustrated fish with gentle water lures, guide them around reef rocks and drifting jellyfish, and bring eight safely home.'}</p><div class="cn-setup"><label>Journey<select id="cnLevel">${levels.map((name,i)=>`<option value="${i+1}" ${level===i+1?'selected':''}>${i+1}. ${name}${player()?.results?.some(r=>r.game===kind&&r.levelId===i+1&&r.completed)?' · completed':''}</option>`).join('')}</select></label><label>Challenge<select id="cnDifficulty">${['Breezy','Gentle','Lively','Wild','Expert'].map((x,i)=>`<option value="${i+1}" ${difficulty===i+1?'selected':''}>${x}</option>`).join('')}</select></label><label>Players<select id="cnPlayers"><option value="1">Solo</option><option value="2" ${ids.length===2?'selected':''} ${DB.profiles.length<2?'disabled':''}>Two-player co-op</option></select></label><label>Partner<select id="cnPartner">${DB.profiles.filter(p=>p.id!==DB.active).map(p=>`<option value="${p.id}" ${p.id===ids[1]?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${cloud?`<label>Graphics<select id="cnQuality"><option value="low" ${quality==='low'?'selected':''}>Low · lighter shadows/effects</option><option value="medium" ${quality==='medium'?'selected':''}>Medium</option><option value="high" ${quality==='high'?'selected':''}>High</option></select></label>`:''}</div><p>${cloud?'Native Xbox controls · keyboard · independent touch sticks. Two controllers or mixed keyboard/touch work together.':'Hold and drag on the water to call fish. Push mode repels instead. Two simultaneous touches own separate lures; a mouse can switch players. Native controller: stick moves lure, hold A to call, B to repel.'} Physical multitouch depends on your screen.</p><button id="cnStart" class="btn primary">${cloud?'TAKE FLIGHT':'ENTER THE LAGOON'}</button><div id="cnRecords" class="cn-records"></div><p id="cnBest">Best on this journey: ${Math.max(0,...(player()?.results||[]).filter(r=>r.game===kind&&r.levelId===level&&r.difficulty===difficulty&&r.competition===(ids.length===2?'coop':'solo')).map(r=>r.score))}</p></section>`;q('#cnExit').onclick=exit;const best=()=>{const competition=q('#cnPlayers').value==='2'?'coop':'solo',rows=DB.profiles.map(p=>({name:p.name,best:Math.max(-1,...p.results.filter(r=>r.game===kind&&r.levelId===level&&r.difficulty===difficulty&&r.competition===competition&&r.ruleset===kind+'-v1').map(r=>r.score))})).filter(p=>p.best>=0).sort((a,b)=>b.best-a.best);q('#cnRecords').innerHTML='<h2>Journey records · '+(competition==='coop'?'co-op':'solo')+'</h2><p>Same journey and challenge only; team records are separate from solo.</p>'+ (rows.length?'<ol>'+rows.map(p=>'<li>'+esc(p.name)+' · '+p.best+' points</li>').join('')+'</ol>':'<p>No records on this challenge yet.</p>');q('#cnBest').textContent='Best on this journey: '+Math.max(0,...(player()?.results||[]).filter(r=>r.game===kind&&r.levelId===level&&r.difficulty===difficulty&&r.competition===(q('#cnPlayers').value==='2'?'coop':'solo')).map(r=>r.score));};best();q('#cnPlayers').onchange=best;q('#cnLevel').onchange=e=>{level=+e.target.value;best();};q('#cnDifficulty').onchange=e=>{difficulty=+e.target.value;best();};q('#cnStart').onclick=()=>{ids=[DB.active];if(q('#cnPlayers').value==='2'){const partner=q('#cnPartner').value;if(!partner||partner===ids[0]){notify('Choose a different partner.');return;}ids.push(partner);}quality=q('#cnQuality')?.value||'medium';gate.show({difficulty:['Breezy','Gentle','Lively','Wild','Expert'][difficulty-1],mode:ids.length===2?'coop':'solo',players:ids.map(id=>player(id).name)},start);};}
 function setPaused(value){if(!model||model.done)return;paused=value;input?.cancel();runtime?.pause(value);sound?.pause(value);musicSound?.pause(value);host.querySelector('.cn-play')?.setAttribute('data-native-gamepad',value?'false':'true');if(q('#cnPause'))q('#cnPause').textContent=value?'RESUME':'PAUSE';if(q('#cnPaused'))q('#cnPaused').hidden=!value;}
 async function start(){cleanup();const token=serial;model=cloud?new Cloudwake({players:ids.length,level,difficulty}):new Inkfin({players:ids.length,level,difficulty});paused=false;recorded=false;acc=0;melody=0;host.innerHTML=`<section class="creative-new cn-play ${kind}" data-native-gamepad="false"><header><button id="cnExit" class="btn secondary">← ARCADE</button><h1>${title}</h1><button id="cnPause" class="btn secondary">PAUSE</button><button id="cnRestart" class="btn secondary">RESTART</button><button id="cnChoose" class="btn secondary">JOURNEYS</button>${cloud?'<button id="cnCamera" class="btn secondary">HARBOR MAP</button>':''}<button id="cnFull" class="btn secondary">FULLSCREEN</button></header><div class="cn-hud" aria-live="off"><strong id="cnStatus">${cloud?'Preparing local 3D engine and floating harbors…':'Gather your school…'}</strong><span id="cnTime"></span></div><div class="cn-stage">${cloud?'<canvas id="cnMap" width="250" height="170" aria-label="Harbor map showing courier positions and destinations"></canvas>':''}<canvas id="cnCanvas" tabindex="0" aria-label="${cloud?'Three-dimensional courier flight':'Illustrated lagoon and touch water lures'}"></canvas><div id="cnPaused" class="cn-pause" hidden><h2>Take a breath.</h2><p>The world and clock are paused. Press RESUME when ready.</p></div></div><div id="cnControls" class="cn-controls">${ids.map((id,i)=>`<section><h2>P${i+1} · ${esc(player(id).name)}</h2><output data-cn-player="${i}"></output>${cloud?`<div class="cn-flight"><div data-flight-stick="${i}" class="cn-stick" role="group" aria-label="Player ${i+1} flight joystick">DRAG TO FLY<span>↑ away · ↓ toward</span></div><div class="cn-buttons">${[['up','CLIMB'],['down','DESCEND'],['dock','DOCK / DELIVER'],['boost','BOOST'],['brake','BRAKE']].map(([key,label])=>`<button data-flight-action="${key}" data-owner="${i}" class="btn secondary">${label}</button>`).join('')}</div></div>`:`<button data-lure-owner="${i}" aria-pressed="${i===0}">MOUSE → PLAYER ${i+1}</button><label><input type="checkbox" data-repel="${i}">Push water instead of call</label>`}</section>`).join('')}</div><p id="cnHint">${cloud?'Dock near the glowing harbor, low (≤3.3m) and slow (≤3.5m/s). Pick up first, then follow your next beacon. Elevated gold rings are optional energy bonuses. P1 WASD/QE/F/Space; P2 arrows/PageDown/PageUp/Enter/Right Shift. Hold left Shift or B to brake.':'Hold a lure just ahead of your school, within its glowing reach. Move gradually around rocks; avoid jellyfish. Release to rest your lure, or hold over a bubbling vent to recharge. P1 WASD + hold F; P2 arrows + hold Enter. Hold Space/Right Shift to push.'}</p><output id="cnMetrics"></output><div id="cnResult" hidden></div></section>`;
 q('#cnExit').onclick=exit;q('#cnPause').onclick=()=>setPaused(!paused);q('#cnRestart').onclick=()=>start();q('#cnChoose').onclick=()=>setup();q('#cnFull').onclick=()=>document.querySelector('#fullscreen')?.click();if(q('#cnCamera'))q('#cnCamera').onclick=()=>{const overview=scene?.toggleCamera();q('#cnCamera').textContent=overview?'FOLLOW COURIERS':'HARBOR MAP';};const canvas=q('#cnCanvas');
 const onHide=()=>{if(document.hidden)setPaused(true);},onBlur=()=>setPaused(true),onResize=()=>{input?.cancel();if(cloud&&runtime)runtime.engine.resize();};document.addEventListener('visibilitychange',onHide);window.addEventListener('blur',onBlur);window.addEventListener('resize',onResize);clean.push(()=>document.removeEventListener('visibilitychange',onHide),()=>window.removeEventListener('blur',onBlur),()=>window.removeEventListener('resize',onResize));
 try{if(cloud){const created=await create3DScene(canvas,{quality,camera:{radius:52,minRadius:28,maxRadius:115,beta:.75,alpha:Math.PI/2,target:[0,2,0]},lighting:{ambient:.68,sun:.95},onError(e){setPaused(true);notify('3D rendering stopped: '+e.message,'error');}});if(disposed||token!==serial){created.dispose();return;}runtime=created;runtime.engine.canvasTabIndex=0;scene=createCloudScene(runtime,model,{getPresentation:()=>DB.settings});}
 if(disposed||token!==serial)return;muteBackground(true);sound=createSynthAudio({contextFactory:audio,ownsContext:false,getSettings:()=>({muted:DB.settings.muted||document.hidden,volume:DB.settings.sound/100*.08})});sound.resume();musicSound=createSynthAudio({contextFactory:audio,ownsContext:false,getSettings:()=>({muted:DB.settings.muted||document.hidden,volume:DB.settings.music/100*.035})});input=createCreativeInput(q('.cn-play'),{kind,count:ids.length,model,enabled:()=>!paused&&!model.done&&!disposed,pause:()=>setPaused(true),help:()=>gate.review()});q('.cn-play').dataset.nativeGamepad=paused?'false':'true';
 if(cloud){runtime.setUpdate(dt=>frame(dt));runtime.pause(document.hidden||paused);if(document.hidden)setPaused(true);}else{stamp=performance.now();const loop=now=>{if(disposed||token!==serial)return;const dt=Math.min(.1,(now-stamp)/1000);stamp=now;frame(paused?0:dt);raf=requestAnimationFrame(loop);};raf=requestAnimationFrame(loop);}frame(0);
 }catch(e){if(disposed||token!==serial)return;cleanup();q('#cnStatus').textContent='Could not start: '+e.message+'. Choose Journeys and retry.';notify(e.message,'error');}}
 function frame(dt){if(!model||disposed)return;const intents=input?.tick(paused||model.done?0:dt)||[];if(!paused&&!model.done){acc=Math.min(.15,acc+dt);while(acc>=1/60){cloud?model.update(1/60,intents):model.update(1/60);acc-=1/60;}if(Math.floor(model.clock/5)>melody){melody=Math.floor(model.clock/5);musicSound?.play({frequency:(cloud?[196,246.94,293.66,392]:[261.63,311.13,392,466.16])[melody%4],duration:cloud?.4:.6,type:'sine',volume:.25});}while(model.events.length){const e=model.events.shift();scene?.event(e);sound?.play({frequency:e.type==='bump'||e.type==='startle'?145:e.type==='pickup'?440:e.type==='ring'?740:cloud?660:880,duration:.16,type:cloud?'triangle':'sine',slide:e.type==='rescue'?150:0,volume:.65});}}
 if(cloud){scene?.update(paused?0:dt);drawMap();}else drawInkfin(q('#cnCanvas'),model,{reduced:!!DB.settings.reduceMotion,effects:DB.settings.presentation?.effects||'full'});q('#cnTime').textContent=`${Math.max(0,Math.ceil(model.limit-model.clock))}s · ${levels[level-1]}`;q('#cnStatus').textContent=cloud?`Team deliveries ${model.players.reduce((n,p)=>n+p.delivered,0)} / ${model.goal*ids.length}`:`${model.saved} / 8 fish home · ${model.fish.filter(f=>!f.rescued).length} still swimming`;for(let i=0;i<ids.length;i++){const el=q(`[data-cn-player="${i}"]`);if(cloud){const p=model.players[i],h=HARBORS[model.job(p)[p.carrying?'destination':'source']];el.textContent=`${p.carrying?'Deliver to':'Pick up at'} ${h.name} · altitude ${p.y.toFixed(1)}m · energy ${Math.round(p.energy)}% · hull ${p.hull}`;}else el.textContent=`Lure energy ${Math.round(model.lures[i].energy)}% · release or use vents to refill`;}
 if(cloud&&scene){const s=scene.stats();q('#cnMetrics').textContent=`${runtime.software?'Canvas compatibility 3D':'WebGL 3D'} · ${s.fps} FPS · ${s.meshes} active meshes · ${s.bodies} physics proxies · ${s.p95Ms.toFixed(1)}ms p95`;}if(model.done&&!recorded)finish();}
 function drawMap(){const c=q('#cnMap'),x=c.getContext('2d');x.fillStyle='#132a3ce8';x.fillRect(0,0,250,170);x.strokeStyle='#759d9b';for(const [i,h]of HARBORS.entries()){const px=125+h.x*5.8,py=85+h.z*5.2;x.beginPath();x.arc(px,py,6,0,7);x.stroke();x.fillStyle='#d6dfce';x.font='10px Outfit';x.textAlign='center';x.fillText(h.name,px,py+(h.z>0?18:-12));}for(const p of model.players){const h=HARBORS[model.job(p)[p.carrying?'destination':'source']];x.strokeStyle=p.id?'#efb990':'#a1e3d6';x.setLineDash([4,4]);x.beginPath();x.moveTo(125+p.x*5.8,85+p.z*5.2);x.lineTo(125+h.x*5.8,85+h.z*5.2);x.stroke();x.setLineDash([]);x.fillStyle=x.strokeStyle;x.beginPath();x.arc(125+p.x*5.8,85+p.z*5.2,5,0,7);x.fill();x.fillText('P'+(p.id+1),125+p.x*5.8,75+p.z*5.2);}}
 function finish(){recorded=true;input.cancel();runtime?.pause(true);sound?.pause(true);musicSound?.pause(true);q('.cn-play').dataset.nativeGamepad='false';const score=model.score();try{for(const id of ids){commitRound([{id,score,hits:cloud?model.players.reduce((n,p)=>n+p.delivered,0):model.saved,errors:cloud?model.players.reduce((n,p)=>n+p.hits,0):model.fish.reduce((n,f)=>n+f.hits,0),duration:model.clock,elapsed:model.clock,completed:model.won,soloWin:model.won,details:{team:ids.length,level}}],{game:kind,difficulty,mode:'solo',ruleset:kind+'-v1',levelId:level,competition:ids.length===2?'coop':'solo',challengeKey:'journey-v1'});if(model.won)unlock(player(id),cloud?'cloudwake-post':'inkfin-home');}save();}catch(e){notify('Could not save this result: '+e.message,'error');}const result=q('#cnResult');result.hidden=false;result.innerHTML=`<h2>${model.won?cloud?'The post has landed.':'A school finds its home.':cloud?'The weather closed in.':'The tide is turning.'}</h2><p>${score} points · ${model.won?'Journey complete':'Try another route and keep practicing'} · ${ids.length===2?'Shared co-op result saved to both profiles; no head-to-head rivalry.':'Solo result saved.'}</p><button id="cnAgain" class="btn primary">PLAY AGAIN</button>${model.won&&level<6?'<button id="cnNext" class="btn primary">NEXT JOURNEY</button>':''}<button id="cnBack" class="btn secondary">CHOOSE JOURNEY</button>`;q('#cnAgain').onclick=start;q('#cnBack').onclick=setup;if(q('#cnNext'))q('#cnNext').onclick=()=>{level++;start();};result.scrollIntoView({block:'nearest'});sound?.pause(false);sound?.play({frequency:model.won?cloud?784:1047:220,duration:.5,type:'sine'});}
 setup();return()=>{disposed=true;cleanup();gate.dispose();host.replaceChildren();};
}
